/// Every key requires complete Simplified Chinese, Traditional Chinese and English copy.
struct UiTextEntry {
    /// Stable resource key and language-indexed immutable strings.
    const char* key;
    const wchar_t* value[3];
    /// Make omitted language columns a compile error instead of a silent fallback.
    constexpr UiTextEntry(const char* resource, const wchar_t* simplified, const wchar_t* traditional, const wchar_t* english)
        : key(resource), value{simplified, traditional, english} {}

};

